  FLAT_NAMES = MAP.map { |old, current| [File.basename(current), File.basename(old)] }.to_h.freeze
  SHELL = <<~'JOBS_NATIVE_LAYOUT'
    # JOBS_SOURCE_LAYOUT_V1：源码同名包装与发布旧平铺目录分别解析，不改变运行时资源名。
    # 保留实际文件路径；只有源码同名包装才向上还原原资源目录。
    jobs_layout_directory() {
      local file="${1:A}" directory="${1:A:h}" levels="${2:-0}"
      [[ "${directory:t}" != "${file:t}" ]] || directory="${directory:h}"
      while (( levels > 0 )); do
        directory="${directory:h}"
        (( levels -= 1 ))
      done
      print -r -- "$directory"
    }
    # 优先兼容已发布的平铺文件，再尝试源码中的同名包装；不跟随链接文件。
    jobs_layout_file() {
      local file="$1" directory="${1:h}" name="${1:t}" candidate="" prefixed=""
      if [[ -f "$file" && ! -L "$file" ]]; then
        print -r -- "$file"
        return 0
      fi
      case "$name" in
        EnableFinderExtension.zsh) prefixed="【MacOS@Xcode】$name" ;;
        *.zsh|*.command|*.sh) [[ "$name" == '【MacOS'* ]] && prefixed="$name" || prefixed="【MacOS】$name" ;;
        *.jxa) prefixed="$name" ;;
        *) print -r -- "$file"; return 0 ;;
      esac
      [[ "${directory:t}" != "$name" ]] || directory="${directory:h}"
      candidate="$directory/$prefixed/$prefixed"
      if [[ ! -L "$directory/$prefixed" && -f "$candidate" && ! -L "$candidate" ]]; then
        print -r -- "$candidate"
      else
        print -r -- "$file"
      fi
    }
  JOBS_NATIVE_LAYOUT
  def self.file(path)
    relative = path.to_s.start_with?(ROOT + '/') ? path.to_s[(ROOT.length + 1)..-1] : nil
    relative && MAP[relative] ? File.join(ROOT, MAP.fetch(relative)) : path
  end
  def self.directory(path)
    relative = path.to_s.start_with?(ROOT + '/') ? path.to_s[(ROOT.length + 1)..-1] : nil
    old = relative && MAP.key(relative)
    old && File.basename(File.dirname(old)) != File.basename(old) ? File.dirname(File.dirname(path)) : File.dirname(path)
  end
  def self.copy(source, destination, **options)
    source = file(source)
    name = FLAT_NAMES.fetch(File.basename(source), File.basename(source))
    destination = File.join(destination, name) if File.directory?(destination)
    FileUtils.cp(source, destination, **options)
  end
  def self.shell(source)
    names = MAP.keys.map { |p| File.basename(p) }.uniq.sort_by { |p| -p.length }
    pattern = /"([^"\n]*\/(?:#{names.map { |p| Regexp.escape(p) }.join('|')}))"/
    prepared = source.lines.map { |line| line.include?("jobs_layout_file") || line.include?("jobs_layout_directory") ? line : line.gsub(pattern) { |path| '"$(jobs_layout_file "' + Regexp.last_match(1) + '")"' } }.join
    prepared = prepared.gsub('${JOBS_TEST_SCRIPT:h}', '$(jobs_layout_directory "$JOBS_TEST_SCRIPT")')
    SHELL + "\n" + prepared
  end
end
